// Agrupa los archivos del vuelo por captura (las 4 bandas + la foto RGB) y elige unas pocas repartidas
// a lo largo del vuelo. Los nombres de dron DJI terminan en _MS_G, _MS_R, _MS_RE, _MS_NIR (bandas) y _D (RGB).
// OJO: ese sufijo no se ha comprobado con archivos reales: si no coincide, aquí es donde hay que ajustarlo.
const cfg = $('Configuración').first().json.config;
const vuelo = $('Datos del vuelo').first().json;
const lista = $input.first().json;
const archivos = Array.isArray(lista.datos) ? lista.datos : [];

const sinExtension = (n) => String(n || '').replace(/\.[^.]+$/, '');
const grupos = new Map();
const grupo = (clave) => {
  if (!grupos.has(clave)) grupos.set(clave, { id: clave, bandas: {}, rgb: null, capturadoEn: null, ubicacion: null, alturaRelativaM: null });
  return grupos.get(clave);
};

for (const a of archivos) {
  const nombre = sinExtension(a.nombreOriginal);
  let g = null;
  if (a.tipo === 'banda_multiespectral' && a.banda) {
    g = grupo(nombre.replace(/_MS_(G|R|RE|NIR)$/i, ''));
    g.bandas[a.banda] = a.id;
  } else if (a.tipo === 'foto_rgb') {
    g = grupo(nombre.replace(/_D$/i, ''));
    g.rgb = a.id;
  }
  if (!g) continue;
  if (!g.capturadoEn && a.capturadoEn) g.capturadoEn = a.capturadoEn;
  if (!g.ubicacion && a.ubicacion && typeof a.ubicacion.latitud === 'number' && typeof a.ubicacion.longitud === 'number') {
    g.ubicacion = { lat: a.ubicacion.latitud, lon: a.ubicacion.longitud };
  }
  if (g.alturaRelativaM === null && a.ubicacion && typeof a.ubicacion.alturaRelativaM === 'number') g.alturaRelativaM = a.ubicacion.alturaRelativaM;
}

const pedirMapas = (() => { try { return $('Entrada (otro flujo)').first().json.mapasInforme === true; } catch (e) { return false; } })();
const todas = [...grupos.values()];
const completas = todas
  .filter((g) => g.bandas.green && g.bandas.red && g.bandas.rededge && g.bandas.nir)
  .sort((a, b) => String(a.capturadoEn || a.id).localeCompare(String(b.capturadoEn || b.id)));
if (completas.length === 0) {
  throw new Error('El vuelo no tiene ninguna captura con las 4 bandas (green, red, rededge y nir). Revisa que se hayan subido todos los archivos _MS_ y su nombre.');
}

// Candidatas: hasta 40 capturas repartidas de forma pareja. El servicio elige entre ellas las `maxCapturas` que analiza,
// solo cenitales (las inclinadas no permiten ubicar zonas) y repartidas por el vuelo.
const k = Math.min(40, completas.length);
const elegidas = [];
for (let i = 0; i < k; i++) elegidas.push(completas[k === 1 ? 0 : Math.round((i * (completas.length - 1)) / (k - 1))]);

const alturas = todas.map((g) => g.alturaRelativaM).filter((v) => typeof v === 'number');
const fechas = todas.map((g) => g.capturadoEn).filter(Boolean).sort();
const meta = {
  cantidadCapturas: completas.length,
  incompletas: todas.length - completas.length,
  alturaRelativaM: alturas.length ? Number((alturas.reduce((s, v) => s + v, 0) / alturas.length).toFixed(1)) : null,
  fecha: String(fechas[0] || vuelo.creadoEn || '').slice(0, 10) || null,
  rtkFijoPct: null, // la lista de archivos no trae la bandera RTK: se deja sin dato
};

return [{ json: {
  cfg,
  vuelo,
  meta,
  peticion: {
    vueloId: vuelo.id,
    umbrales: cfg.umbrales,
    siembra: cfg.siembra,
    maxImagenes: cfg.maxCapturas,
    capturas: elegidas.map((g) => ({ id: g.id, bandas: g.bandas, rgb: g.rgb, ubicacion: g.ubicacion, capturadoEn: g.capturadoEn })),
    // Todas las capturas (solo NIR): el servicio mide el GSD efectivo con pares consecutivos, que las elegidas no son
    capturasEscala: completas.slice(0, 400).map((g) => ({ id: g.id, bandas: { nir: g.bandas.nir }, capturadoEn: g.capturadoEn })),
    // Mosaico aproximado del vuelo: solo si el flujo 03 pide los mapas (cuesta unos segundos y pesa ~1 MB)
    ...(pedirMapas ? { capturasMosaico: completas.slice(0, 400).map((g) => ({ id: g.id, bandas: g.bandas, capturadoEn: g.capturadoEn })) } : {}),
  },
} }];

// Arma lo que se le envía al modelo de visión: las cifras ya calculadas y las imágenes (mapas de calor y foto RGB).
const previo = $('Agrupar capturas').first().json;
const r = $input.first().json; // respuesta del servicio de índices
if (!Array.isArray(r.indices) || r.indices.length === 0) throw new Error('El servicio de índices no devolvió ningún índice.');
const mapas = Array.isArray(r.mapas) ? r.mapas : [];
const candidatas = Array.isArray(r.zonasCandidatas) ? r.zonasCandidatas : [];

const sistema = [
  'Eres un analista de imágenes multiespectrales de cultivos de café. Recibes cifras ya calculadas y mapas de calor de índices de vegetación (NDVI, NDRE, GNDVI), más una foto RGB.',
  '',
  'Reglas obligatorias:',
  '1. Describe SOLO lo que se ve en las imágenes y lo que dicen las cifras. No inventes cifras ni zonas: solo puedes hablar de las zonas candidatas que vienen en los datos (por su id).',
  '2. Un índice bajo indica vigor reducido, no la causa. No diagnostiques enfermedades, plagas ni deficiencias. Di que la causa debe confirmarse en campo.',
  '3. Califica la severidad de cada zona candidata como alta, media, baja o informativa, según su valor frente al umbral y su extensión.',
  '4. Si una imagen no permite concluir algo (sombras, bordes, poca resolución), dilo en "limitaciones".',
  '5. Sé breve: cada descripción de zona, máximo 20 palabras; hasta 4 observaciones y hasta 3 limitaciones. La respuesta total no puede pasar de 700 palabras.',
  '6. Responde ÚNICAMENTE con un objeto JSON, sin texto adicional ni bloques de código, con esta forma:',
  '{"observaciones":["..."],"zonas":[{"id":"id de la zona candidata","descripcion":"qué se ve en esa zona","severidad":"alta|media|baja|informativa"}],"confianza":"alta|media|baja","limitaciones":["..."]}',
].join('\n');

const resumen = { variabilidadEspacial: { nivel: r.variabilidadEspacial?.nivel ?? null }, indices: r.indices.map(({ desviacion, cv, ...indice }) => indice), vigor: r.vigor, cobertura: r.cobertura, zonasCandidatas: candidatas.map((z) => ({ id: z.id, indice: z.indice, valor: z.valor, areaPct: z.areaPct, capturaId: z.capturaId })) };
const partes = [{ type: 'text', text: 'Datos calculados (JSON):\n' + JSON.stringify(resumen) + '\n\nA continuación van las imágenes, cada una con su título.' }];
for (const m of mapas.slice(0, 2)) {
  partes.push({ type: 'text', text: 'Imagen: ' + (m.titulo || m.indice || 'sin título') + ' (captura ' + (m.capturaId || '?') + ')' });
  partes.push({ type: 'image_url', image_url: { url: 'data:' + (m.mime || 'image/png') + ';base64,' + m.base64 } });
}

return [{ json: {
  cfg: previo.cfg,
  vuelo: previo.vuelo,
  meta: previo.meta,
  servicio: { ficha: r.ficha ?? null, variabilidadEspacial: r.variabilidadEspacial ?? null, correlacionApp: r.correlacionApp ?? null, indices: r.indices, vigor: r.vigor || null, cobertura: r.cobertura || null, siembra: r.siembra || null, plantas: r.plantas ?? null, huellas: r.huellas ?? null, mapasInforme: Array.isArray(r.mapasInforme) ? r.mapasInforme : [], mosaicos: Array.isArray(r.mosaicos) ? r.mosaicos : [], zonasCandidatas: candidatas, advertencias: Array.isArray(r.advertencias) ? r.advertencias : [] },
  mensajes: [{ role: 'system', content: sistema }, { role: 'user', content: partes }],
} }];

// Junta lo calculado por el servicio (cifras) con lo que dice el modelo de visión (texto y severidad).
// Las cifras NUNCA salen del modelo: vienen del servicio.
const previo = $('Preparar imágenes para el modelo').first().json;
const resp = $input.first().json;
if (resp.statusCode !== 200) {
  const detalle = resp.body && resp.body.error && resp.body.error.message ? resp.body.error.message : JSON.stringify(resp.body);
  throw new Error('El modelo de visión respondió ' + resp.statusCode + ': ' + String(detalle).slice(0, 300));
}

const eleccion = resp.body.choices && resp.body.choices[0] ? resp.body.choices[0] : {};
let texto = eleccion.message && typeof eleccion.message.content === 'string' ? eleccion.message.content : '';
texto = texto.replace(/<think>[\s\S]*?<\/think>/g, '').trim();
if (!texto) throw new Error('El modelo de visión no devolvió texto (finish_reason: ' + (eleccion.finish_reason || '?') + '). Sube max_tokens o baja el razonamiento.');
const ini = texto.indexOf('{');
const fin = texto.lastIndexOf('}');
if (ini < 0 || fin < ini) throw new Error('La respuesta del modelo de visión no contiene un JSON.');
let crudo;
try {
  crudo = JSON.parse(texto.slice(ini, fin + 1));
} catch (e) {
  throw new Error('El JSON del modelo de visión no es válido: ' + e.message);
}

const SEVERIDADES = ['alta', 'media', 'baja', 'informativa'];
const CONFIANZAS = ['alta', 'media', 'baja'];
const txt = (v) => (typeof v === 'string' ? v.trim() : '');
const lista = (v) => (Array.isArray(v) ? v : []);
const delModelo = new Map(lista(crudo.zonas).map((z) => [String(z && z.id), z]));

const NOTA_CONTEO = "Estimación experimental por detección de copas en NIR, sin validar. Contra conteos manuales en cuatro recortes el error observado fue de −19 % a +46 % según la zona, y el pasto brillante y las masas de follaje dan falsos positivos.";
const { servicio, meta, vuelo: v } = previo;
const zonas = servicio.zonasCandidatas.map((z) => {
  const d = delModelo.get(String(z.id)) || {};
  return {
    id: z.id,
    descripcion: txt(d.descripcion) || 'Zona detectada con el índice ' + z.indice,
    severidad: SEVERIDADES.includes(d.severidad) ? d.severidad : 'informativa',
    indice: z.indice,
    valor: z.valor,
    ubicacion: z.ubicacion || null,
    ubicacionZona: z.ubicacionZona ?? null,
    areaM2: z.areaM2 ?? null,
    gsdOrigen: z.gsdOrigen ?? null,
    poligono: z.poligono ?? null,
    indicesAfectados: z.indicesAfectados ?? null,
    detecciones: z.detecciones ?? 1,
  };
});

const limitaciones = [...new Set([
  ...servicio.advertencias,
  ...lista(crudo.limitaciones).map(txt),
  meta.incompletas > 0 ? meta.incompletas + ' capturas sin las 4 bandas no se usaron.' : '',
].filter(Boolean))];

const uso = resp.body.usage || {};
const pedirMapas = (() => { try { return $('Entrada (otro flujo)').first().json.mapasInforme === true; } catch (e) { return false; } })(); // los mapas pesan ~1 MB: solo para el PDF, nunca para el chat
// El chat (sin mapasInforme) no necesita geometrías: huellas, polígonos y celdas o registros por captura pasan de 8000 tokens por minuto del modelo.
const compactarParaChat = (salida) => {
  if (pedirMapas) return salida;
  const a = salida[0].json.analisis;
  a.huellas = null;
  a.zonas = a.zonas.map(({ poligono, ...z }) => z);
  if (a.correlacionApp) { const { celdas, porCaptura, ...c } = a.correlacionApp; a.correlacionApp = c; }
  return salida;
};
return compactarParaChat([{ json: {
    mapasInforme: pedirMapas ? (Array.isArray(servicio.mapasInforme) ? servicio.mapasInforme : []) : [], mosaicos: pedirMapas ? (Array.isArray(servicio.mosaicos) ? servicio.mosaicos : []) : [],
  vuelo: { id: v.id, nombre: v.nombre, lote: v.lote || null, fecha: meta.fecha, notas: v.notas || null, alturaRelativaM: meta.alturaRelativaM, rtkFijoPct: meta.rtkFijoPct, cantidadCapturas: meta.cantidadCapturas },
  analisis: {
    generadoEn: new Date().toISOString(),
    indices: servicio.indices,
    ficha: servicio.ficha ?? null,
    variabilidadEspacial: servicio.variabilidadEspacial ?? null,
    correlacionApp: servicio.correlacionApp ?? null,
    vigor: servicio.vigor || null,
    cobertura: servicio.cobertura || null,
    siembra: servicio.siembra || null,
    plantas: servicio.plantas ? { ...servicio.plantas, notaValidacion: NOTA_CONTEO } : null, huellas: servicio.huellas ?? null,
    zonas,
    observaciones: lista(crudo.observaciones).map(txt).filter(Boolean),
    confianza: CONFIANZAS.includes(crudo.confianza) ? crudo.confianza : 'baja',
    limitaciones,
  },
  consumoVision: { entrada: uso.prompt_tokens || 0, salida: uso.completion_tokens || 0, razonamiento: (uso.completion_tokens_details && uso.completion_tokens_details.reasoning_tokens) || 0 },
} }]);

// Análisis SIN modelo de IA: todo sale del servicio de índices y de reglas fijas.
// Se usa cuando config.usarModeloVision es false. Misma salida que "Armar análisis".
const previo = $('Agrupar capturas').first().json;
const sinVisionPorFallo = $input.first().json.statusCode !== undefined; // llegó desde el modelo de visión que falló (p. ej. límite de uso)
const r = $('Correlacionar con la app').first().json; // respuesta del servicio de índices con la correlación
if (!Array.isArray(r.indices) || r.indices.length === 0) throw new Error('El servicio de índices no devolvió ningún índice.');
const { meta, vuelo: v } = previo;
const umbrales = previo.cfg.umbrales || {};
const advertencias = Array.isArray(r.advertencias) ? r.advertencias : [];
const NOTA_CONTEO = "Estimación experimental por detección de copas en NIR, sin validar. Contra conteos manuales en cuatro recortes el error observado fue de −19 % a +46 % según la zona, y el pasto brillante y las masas de follaje dan falsos positivos.";
const candidatas = Array.isArray(r.zonasCandidatas) ? r.zonasCandidatas : [];

// Severidad por regla: cuánto baja del umbral (déficit) y qué extensión ocupa (areaPct)
const severidad = (z) => {
  const deficit = (umbrales[z.indice] ?? 0.5) - z.valor;
  if (z.areaPct < 2) return 'informativa';
  if (deficit >= 0.3 && z.areaPct >= 10) return 'alta';
  if (deficit >= 0.15 || z.areaPct >= 10) return 'media';
  return 'baja';
};

const zonas = candidatas.map((z) => ({
  id: z.id,
  descripcion: 'Zona con ' + ((z.indicesAfectados || []).map((i) => i.indice).join(', ') || z.indice) + ' bajo el umbral' + ((z.detecciones || 1) > 1 ? ' (detectada ' + z.detecciones + ' veces entre índices y capturas que se solapan)' : ' en la captura ' + z.capturaId) + '. Causa por confirmar en campo.',
  severidad: severidad(z),
  indice: z.indice,
  valor: z.valor,
  ubicacion: z.ubicacion || null,
  ubicacionZona: z.ubicacionZona ?? null,
  areaM2: z.areaM2 ?? null,
  gsdOrigen: z.gsdOrigen ?? null,
  poligono: z.poligono ?? null,
  indicesAfectados: z.indicesAfectados ?? null,
  detecciones: z.detecciones ?? 1,
}));

const observaciones = r.indices.map((i) =>
  i.nombre + ': media ' + i.media + ', mediana ' + i.mediana + '; ' + i.areaBajoUmbralPct + ' % del área bajo el umbral ' + i.umbral + '.');

const limitaciones = [...new Set([
  ...advertencias,
  'Análisis automático por reglas, sin interpretación de las imágenes por un modelo de visión.',
  sinVisionPorFallo ? 'El modelo de visión no estuvo disponible en este momento (por ejemplo, límite de uso): se usaron solo las cifras calculadas.' : '',
  meta.incompletas > 0 ? meta.incompletas + ' capturas sin las 4 bandas no se usaron.' : '',
].filter(Boolean))];

const pedirMapas = (() => { try { return $('Entrada (otro flujo)').first().json.mapasInforme === true; } catch (e) { return false; } })(); // los mapas pesan ~1 MB: solo para el PDF, nunca para el chat
// El chat (sin mapasInforme) no necesita geometrías: huellas, polígonos y celdas o registros por captura pasan de 8000 tokens por minuto del modelo.
const compactarParaChat = (salida) => {
  if (pedirMapas) return salida;
  const a = salida[0].json.analisis;
  a.huellas = null;
  a.zonas = a.zonas.map(({ poligono, ...z }) => z);
  if (a.correlacionApp) { const { celdas, porCaptura, ...c } = a.correlacionApp; a.correlacionApp = c; }
  return salida;
};
return compactarParaChat([{ json: {
    mapasInforme: pedirMapas ? (Array.isArray(r.mapasInforme) ? r.mapasInforme : []) : [], mosaicos: pedirMapas ? (Array.isArray(r.mosaicos) ? r.mosaicos : []) : [],
  vuelo: { id: v.id, nombre: v.nombre, lote: v.lote || null, fecha: meta.fecha, notas: v.notas || null, alturaRelativaM: meta.alturaRelativaM, rtkFijoPct: meta.rtkFijoPct, cantidadCapturas: meta.cantidadCapturas },
  analisis: { generadoEn: new Date().toISOString(), indices: r.indices, ficha: r.ficha ?? null, variabilidadEspacial: r.variabilidadEspacial ?? null, correlacionApp: r.correlacionApp ?? null, vigor: r.vigor || null, cobertura: r.cobertura || null, siembra: r.siembra || null, plantas: r.plantas ? { ...r.plantas, notaValidacion: NOTA_CONTEO } : null, huellas: r.huellas ?? null, zonas, observaciones, confianza: 'baja', limitaciones },
  consumoVision: { entrada: 0, salida: 0, razonamiento: 0 },
} }]);

// Solo salen conteos, fechas y celdas agregadas de ~25 m: nunca los registros ni sus coordenadas exactas.
const respuestaServicio = $('Calcular índices (servicio)').first().json;
const config = $('Configuración').first().json.config;
const resp = $input.first().json;
const radioM = config.radioCorrelacionM;
const base = [
  'La correlación es asociación espacial y no demuestra causalidad.',
  'El porcentaje de incidencia de la app no se guarda en el servidor, por lo que no se compara.',
];
const salida = (correlacionApp, limitaciones) => [{ json: {
  ...respuestaServicio, correlacionApp,
  advertencias: [...(Array.isArray(respuestaServicio.advertencias) ? respuestaServicio.advertencias : []), ...limitaciones],
} }];
const app = resp.body;
if (resp.error || !Number.isInteger(resp.statusCode) || resp.statusCode < 200 || resp.statusCode >= 300 || !app || !Array.isArray(app.registros) || !Number.isFinite(radioM) || radioM < 0) {
  return salida(null, [...base,
    'Las fechas de la app y del vuelo pueden diferir; diferencia en días no disponible.',
    'No se pudo obtener la correlación con la app (error de consulta o respuesta inválida). El análisis del vuelo continúa.',
  ]);
}
const registros = app.registros;
const dias = registros.map((r) => r.diasDesdeVuelo).filter(Number.isFinite);
const un_decimal = (v) => Math.round(v * 10) / 10;
const diasMinDesdeVuelo = dias.length ? un_decimal(Math.min(...dias)) : null;
const diasMaxDesdeVuelo = dias.length ? un_decimal(Math.max(...dias)) : null;
const fechas = registros.map((r) => r.fecha).filter((f) => typeof f === 'string' && Number.isFinite(Date.parse(f))).sort((a, b) => Date.parse(a) - Date.parse(b));
const limitaciones = [...base, ...(Array.isArray(app.limitaciones) ? app.limitaciones : []),
  dias.length ? `Las fechas de la app y del vuelo pueden diferir: entre ${diasMinDesdeVuelo} y ${diasMaxDesdeVuelo} días desde el vuelo (negativos: anteriores; positivos: posteriores).` : 'Las fechas de la app y del vuelo pueden diferir; diferencia en días no disponible.',
];
if (dias.length < registros.length) limitaciones.push('Hay registros sin diferencia temporal disponible.');
if (app.truncado) limitaciones.push('La respuesta de la app está truncada: los conteos y rangos temporales se limitan a los registros recibidos.');
const coordenadas = (lat, lon) => Number.isFinite(lat) && Number.isFinite(lon) && Math.abs(lat) <= 90 && Math.abs(lon) <= 180;
const validos = registros.filter((r) => coordenadas(r.latitud, r.longitud));
if (validos.length !== registros.length) limitaciones.push('Se omitieron registros sin coordenadas válidas en los conteos espaciales.');
const distancia = (a, b) => {
  const rad = (v) => v * Math.PI / 180;
  const h = Math.sin(rad(b.latitud - a.lat) / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.latitud)) * Math.sin(rad(b.longitud - a.lon) / 2) ** 2;
  return 6371000 * 2 * Math.asin(Math.sqrt(Math.max(0, Math.min(1, h))));
};
const candidatas = Array.isArray(respuestaServicio.zonasCandidatas) ? respuestaServicio.zonasCandidatas : [];
// Las zonas se ubican en el centro de su captura (no hay georreferencia por píxel): la cercanía se calcula
// por captura y las zonas de una misma captura comparten el resultado.
const candidatas_peticion = ($('Agrupar capturas').first().json.peticion || {}).capturas || [];
// Solo las capturas que el servicio analizó de verdad (elige entre las candidatas, solo cenitales)
const analizadas = Array.isArray(respuestaServicio.capturasAnalizadas) ? new Set(respuestaServicio.capturasAnalizadas) : null;
const capturas = analizadas ? candidatas_peticion.filter((c) => analizadas.has(c.id)) : candidatas_peticion;
const conUbicacion = capturas.filter((c) => c.ubicacion && coordenadas(c.ubicacion.lat, c.ubicacion.lon));
const porCaptura = conUbicacion.map((c) => {
  const cercanos = validos.filter((r) => distancia(c.ubicacion, r) <= radioM);
  const clases = Object.create(null);
  for (const r of cercanos) {
    const clase = r.clase ?? 'sin clase';
    clases[clase] = (clases[clase] ?? 0) + 1;
  }
  return { capturaId: c.id, zonas: candidatas.filter((z) => z.capturaId === c.id).map((z) => z.id), cercanos: cercanos.length, clases };
});
if (conUbicacion.length < capturas.length) limitaciones.push('Las capturas sin georreferencia no tienen conteos de cercanía.');
const registrosCercanos = validos.filter((r) => conUbicacion.some((c) => distancia(c.ubicacion, r) <= radioM)).length;
// Huellas reales de las capturas (GPS RTK, yaw y GSD, terreno plano): mejor que la caja, pero no son el lindero del lote.
const huellas = Array.isArray(respuestaServicio.huellas) ? respuestaServicio.huellas.filter((h) => Array.isArray(h.poligono) && h.poligono.length >= 3) : [];
const dentro = (r, poligono) => {
  let ins = false;
  for (let i = 0, j = poligono.length - 1; i < poligono.length; j = i++) {
    const [yi, xi] = poligono[i]; const [yj, xj] = poligono[j];
    if ((yi > r.latitud) !== (yj > r.latitud) && r.longitud < (xj - xi) * (r.latitud - yi) / (yj - yi) + xi) ins = !ins;
  }
  return ins;
};
